  productReviewVotes      ecommerce_mall_product_review_votes[]
  productReviewReports    ecommerce_mall_product_review_reports[]
  reviewEligibilities     ecommerce_mall_review_eligibilities[]
  auditTrails             ecommerce_mall_inventory_audit_trails[]
  notificationEvents      ecommerce_mall_notification_events[]
