  ecommerce_mall_customer_id String @db.Uuid

  /// Unique order identifier displayed to customers for reference and tracking
  /// purposes.
  order_number String

  /// Primary street address line for order delivery.
  shipping_address_line1 String

  /// Secondary address line for apartment, suite, or unit number.
  shipping_address_line2 String?

  /// City for order delivery address.
  shipping_city String

  /// State or province for order delivery address.
  shipping_state String

  /// Postal code or ZIP code for order delivery address.
  shipping_postal_code String

  /// Country for order delivery address.
  shipping_country String

  /// Total cost of all order items before taxes and shipping.
  subtotal_amount Float @db.DoublePrecision

  /// Total shipping cost for the entire order.
  shipping_amount Float @db.DoublePrecision

  /// Total tax amount calculated for the order.
  tax_amount Float @db.DoublePrecision

